/* 平台层 UI：通用首页/赛事发现/后续服务预告。预告没有业务写入，不新增一期交付承诺。 */
const Platform=(()=>{
const {icon:I,esc:E,badge:B,yuan:Y}=UI;
let sport='all',status='all',search='';
const sports=[['all','全部项目'],['badminton','羽毛球'],['running','跑步'],['basketball','篮球'],['football','足球'],['tennis','网球']];
const future={venues:{title:'场馆服务',tag:'场馆与场地',icon:'pin',intro:'把运动的下一站，安排在身边。',copy:'未来，你可以在这里发现本地运动场所、了解场地信息与相关服务。',items:[['发现场馆','按运动需求寻找身边的运动空间。'],['了解场地','场地条件、开放信息与服务说明。'],['预约与使用','商业预约属于后续业务，办理规则另行确认。']],back:'回到首页'},life:{title:'运动生活',tag:'同城运动与体育资讯',icon:'people',intro:'从一次参赛，到每天都想动一动。',copy:'同城活动、体育信息与本地服务，将在这里形成更丰富的运动生活入口。',items:[['同城运动','发现本地运动活动，连接身边的运动伙伴。'],['体育动态','了解城市体育资讯、赛事动态与运动内容。'],['本地服务','运动相关服务与撮合方向，具体范围后续确认。']],back:'回到首页'}};
const phaseText=()=>({registration:'报名中',registration_closed:'报名已截止',ongoing:'进行中',finished:'已结束'})[UI.s.phase];
const cityMark=()=>`<button class="city-selector" data-platform="city" aria-label="当前城市保定">${I('pin')}<span>保定</span><span class="city-mini">城市站</span></button>`;
const scene=()=>`<svg class="platform-scene" viewBox="0 0 580 400" aria-hidden="true"><defs><pattern id="city-grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M0 35V0h35" fill="none" stroke="#dbe6d7" stroke-width=".5"/></pattern></defs><rect width="580" height="400" fill="url(#city-grid)"/><circle cx="442" cy="100" r="55" fill="#f2ceab"/><circle cx="442" cy="100" r="84" fill="none" stroke="#cddcc5"/>
<g opacity=".5" fill="none" stroke="#809b80" stroke-width="1.5"><path d="M28 239h39v-58h82v58h27m-111-58 10-13h63l13 13m-94-13 20-13h49l20 13M82 155v-17h43v17m-42-17 22-15 22 15M83 196v29m15-29v29m14-29v29m15-29v29M383 239h141m-102-15v-58h70v58m-80-58 18-7 12-11h35l12 11 18 7m-105 0h103m-88-7h72m-50-22 8-8 9 8m-34 36v48m18-48v48m18-48v48m-47-15h66"/><path d="M33 257h498m-485 10h466" stroke="#b5c8ae"/></g>
<g fill="none" stroke="#d49b7b" stroke-width="1" opacity=".75"><path d="M139 251q23-30 52 0m-36-4q3-23 8-31 12 13 8 31m-4 3q14-21 30-11-5 16-30 11m-6 0q-20-17-31-4 7 10 31 4"/></g>
<g transform="translate(93 174)"><ellipse cx="186" cy="120" rx="181" ry="71" fill="#b7d1af"/><ellipse cx="186" cy="120" rx="171" ry="61" fill="none" stroke="#eff6df" stroke-width="2"/><ellipse cx="186" cy="120" rx="154" ry="49" fill="none" stroke="#eff6df" stroke-width="1.8"/><ellipse cx="186" cy="120" rx="137" ry="37" fill="none" stroke="#eff6df" stroke-width="1.8"/><ellipse cx="186" cy="120" rx="116" ry="24" fill="#6e9e79"/><path d="m295 149 36 27m-54-40 41 30" stroke="#eff6df" stroke-width="2"/></g>
<g transform="translate(262 105)"><ellipse cx="30" cy="225" rx="54" ry="10" fill="#3f7150" opacity=".16"/><circle cx="53" cy="18" r="13" fill="#214f40"/><path d="m46 38-25 44 29 13 29-44Z" fill="#d77142"/><path d="m50 45-29-10-25 17m76 4 24 23 27-11" fill="none" stroke="#214f40" stroke-width="10" stroke-linecap="round"/><path d="m27 89-23 39-37 14m80-46 26 41-10 43" fill="none" stroke="#214f40" stroke-width="13" stroke-linecap="round"/><path d="m-34 142-13 4m108 33 12 2" stroke="#f1ead7" stroke-width="8" stroke-linecap="round"/></g>
<g transform="translate(425 220) rotate(18)"><circle cx="33" cy="35" r="34" fill="#eabe88"/><path d="M0 35h66M33 1v68M11 8q41 23 10 58M53 8Q10 29 45 68" fill="none" stroke="#ab7648" stroke-width="1.5"/></g><g transform="translate(88 110) rotate(-17)"><ellipse cx="21" cy="26" rx="20" ry="29" fill="#eff1dc" stroke="#658d70" stroke-width="3"/><path d="M9 3v45m12-49v57M33 3v45M2 15h38M1 28h40M5 42h33" stroke="#b7cba9" stroke-width="1"/><path d="M21 55v39" stroke="#658d70" stroke-width="5"/></g><path d="M175 69h12m-6-6v12M475 316h12m-6-6v12" stroke="#d99a6b" stroke-width="2"/><circle cx="195" cy="103" r="4" fill="#dfb78d"/></svg>`;
function card(historic=false){if(historic)return `<article class="card event-card"><div class="event-cover two"><span class="event-cover-tag">羽毛球 · 已结束 · 示例</span><div class="mini-art">${UI.art()}</div><span class="event-cover-title">夏末的最后一拍</span></div><div class="event-body"><div class="between">${B('交流赛','gray')}${B('已结束','gray')}</div><h3 class="mt">夏末羽毛球友谊赛</h3><div class="event-meta"><span>${I('calendar')}09月19日 — 09月20日</span><span>${I('pin')}保定 · 城市运动馆（示例）</span></div><div class="between event-bottom"><span class="small muted">报名已结束</span><button class="btn text slim" data-action="history">查看介绍</button></div></div></article>`;
return `<a class="card event-card" href="#detail"><div class="event-cover"><span class="event-cover-tag">羽毛球 · 交流赛 · 示例</span><div class="mini-art">${UI.art()}</div><span class="event-cover-title">秋日挥拍 · 一起上场</span></div><div class="event-body"><div class="between">${B('单打 / 双打','gray')}${B(UI.normal()?phaseText():'已取消',UI.normal()&&UI.s.phase==='registration'?'':UI.normal()?'gray':'red')}</div><h3 class="mt">2026 秋季羽毛球交流赛</h3><div class="event-meta"><span>${I('calendar')}10月24日 — 10月25日</span><span>${I('pin')}保定 · 城市运动馆（示例）</span></div><div class="between event-bottom"><span class="money">${UI.s.mode.endsWith('free')?'免费':'免费 / ¥60 起'}</span><span class="small">查看项目 ${I('arrow')}</span></div></div></a>`}
function home(shell){shell(`<section class="platform-hero"><div class="platform-hero-copy"><span class="city-eyebrow"><span class="city-line"></span>保定 · 身边的运动生活</span><h1>在古城，<br>找到运动的<br><em>每一种可能。</em></h1><p><span class="hero-intro-desktop">从一场比赛出发，连接身边的场地与伙伴。<br>让运动，成为这座城市的日常。</span><span class="hero-intro-mobile">发现身边的赛事，和古城一起动起来。</span></p><div class="row wrap"><a href="#events" class="btn primary big">发现赛事 ${I('arrow')}</a><a href="#orders" class="btn text">我的参赛</a></div><div class="hero-location">${I('pin')} 立足保定，连接你身边的运动</div></div><div class="platform-hero-art">${scene()}<span class="city-art-caption">古城有来处 · 运动有新意</span><span class="scene-label label-run">RUN / 跑步</span><span class="scene-label label-play">PLAY / 球类</span></div></section><div class="section-head section-title"><div><span class="eyebrow">从身边开始</span><h2>近期赛事</h2></div><a href="#events" class="btn text">全部赛事 ${I('arrow')}</a></div><div class="home-events">${UI.s.publication==='published'?card():`<div class="card empty"><h3>暂没有公开赛事</h3><p>已有关联记录可在“我的参赛”查看。</p></div>`}${card(true)}<div class="local-note"><span class="local-note-label">保定 · 一起动起来</span><div class="city-symbol">${I('pin')}</div><h3>熟悉的城市，<br>新的运动相遇。</h3><p>把赛事与日常连接起来，<br>把热爱留在生活里。</p><div class="local-note-rule"></div><span>AI运动 · 保定城市站</span></div></div><a class="host-callout" href="organizer.html#apply"><span class="shortcut-icon pale">${I('settings')}</span><div><strong>我要办赛</strong><span>申请开通办赛空间、查看审核进度</span></div>${I('arrow')}</a><div class="section-head section-title"><div><span class="eyebrow">平台正在生长</span><h2>更多运动服务</h2></div><span class="muted small">规划预告 · 尚未开放</span></div><div class="future-services"><a href="#future/venues" class="future-card"><span class="future-icon">${I('pin')}</span><div><div class="row"><h3>场馆服务</h3>${B('后续规划','gray')}</div><p>发现身边场馆，连接场地服务</p></div><span class="future-view">了解规划 ${I('chevron')}</span></a><a href="#future/life" class="future-card"><span class="future-icon warm">${I('people')}</span><div><div class="row"><h3>运动生活</h3>${B('后续规划','gray')}</div><p>同城活动、体育动态与本地服务</p></div><span class="future-view">了解规划 ${I('chevron')}</span></a></div><p class="future-footnote">当前开放赛事试点体验。场馆与运动生活入口仅介绍方向，具体能力及开放安排另行确定。</p>`,'home')}
function events(shell){const eligible=UI.s.publication==='published'&&sport!=='none'&&['all','badminton'].includes(sport)&&(!search||'2026 秋季羽毛球交流赛'.includes(search));const live=eligible&&(status==='all'||status==='open'&&UI.normal()&&UI.s.phase==='registration');const history=['all','badminton'].includes(sport)&&status!=='open'&&(!search||'夏末羽毛球友谊赛'.includes(search));const futureSport=!['all','badminton'].includes(sport);shell(`<div class="event-directory-head"><div><span class="city-eyebrow">保定 · 赛事发现</span><h1>找到属于你的赛场。</h1><p>按运动项目与赛事状态，选择你想参与的一场。</p></div><div class="directory-city">${I('pin')}<span>当前城市<strong>保定</strong></span></div></div><section class="catalog-filters"><div class="filter-line"><span class="filter-label">运动项目</span><div class="sport-chips">${sports.map(([id,n])=>`<button class="chip ${sport===id?'active':''}" data-platform="sport" data-id="${id}">${n}${['all','badminton'].includes(id)?'':'<span class="chip-future-dot" aria-label="尚未开放"></span>'}</button>`).join('')}</div></div><div class="filter-line"><span class="filter-label">赛事状态</span><div class="sport-chips">${[['all','全部赛事'],['open','可报名'],['finished','已结束']].map(([id,n])=>`<button class="chip ${status===id?'active':''}" data-platform="status" data-id="${id}">${n}</button>`).join('')}</div><div class="catalog-search"><input id="event-query" aria-label="搜索赛事名称" placeholder="搜索赛事名称" value="${E(search)}"><button class="btn text" data-platform="search" aria-label="搜索">${I('search')}</button></div></div></section><div class="between" style="margin:24px 0 18px"><span class="small muted">${futureSport?'项目尚未开放':`找到 ${Number(live)+Number(history)} 场示例赛事`}</span><span class="small muted">${futureSport?'预告与可报名项目分别展示':'当前试点：羽毛球 · 其他项目逐步扩展'}</span></div>${futureSport?`<section class="card future-sport-empty"><span class="empty-orbit">${I(sport==='running'?'clock':'shuttle')}</span><h2>${sports.find(x=>x[0]===sport)[1]}赛事，期待一起上场。</h2><p>本项目尚未开放报名。未来赛事会在同一平台中按自身参赛方式与规则展示，<br>不会套用羽毛球的单打、双打或比分结构。</p><button class="btn primary" data-platform="sport" data-id="badminton">查看当前可参与项目 ${I('arrow')}</button><p class="entry-note mt">不提供虚构赛程、报名按钮或开放日期。</p></section>`:live||history?`<div class="grid3">${live?card():''}${history?card(true):''}</div>`:`<section class="card empty">${I('search')}<h3>没有符合条件的赛事</h3><p>试试其他筛选条件；已有报名可在“我的参赛”继续查看。</p><button class="btn mt" data-platform="reset-filters">清除筛选</button></section>`}${UI.scenarios()}`,'events')}
function upcoming(shell,key){const f=future[key]||future.venues;shell(`<div class="crumb"><a href="#home">首页</a>${I('chevron')}<span>${f.title}</span></div><section class="upcoming-hero"><span class="eyebrow">${f.tag} · 后续规划</span><h1>${f.intro}</h1><p>${f.copy}</p><div class="row wrap">${B('敬请期待','orange')}<span class="small muted">尚未开放 · 具体业务规则和安排待确认</span></div></section><div class="section-head section-title"><h2>可以期待的方向</h2><span class="small muted">服务愿景，非当前能力</span></div><div class="grid3">${f.items.map(([title,text],i)=>`<section class="card future-step"><span>0${i+1}</span><h3>${title}</h3><p>${text}</p></section>`).join('')}</div><div class="future-return"><a href="#home" class="btn">${I('back')} 回到首页</a><a href="#events" class="btn primary">先发现一场赛事 ${I('arrow')}</a></div><p class="future-footnote">这个入口用于介绍平台方向，没有预约、交易、内容发布或匹配操作，也不承诺开放时间。</p>`,'home')}
function bUpcoming(key){const f=key==='venues'?future.venues:future.life;return `<div class="crumb"><span>平台工作台</span>${I('chevron')}<span>${key==='venues'?'场馆运营':'内容与生活服务'}</span></div><div class="b-future-head"><span class="eyebrow">独立业务空间 · 后续规划</span><h1 class="b-page-title">${key==='venues'?'场馆运营空间':'内容与生活服务空间'}</h1><p class="muted">${key==='venues'?'未来在同一平台中管理场馆及场地业务。':'未来承接体育内容、本地运动服务与相关运营。'}</p>${B('敬请期待','orange')}</div><div class="grid3 mt">${(key==='venues'?[['场馆与场地','设施信息、场地与使用条件。'],['资源与时段','赛事资源使用与冲突协调。'],['运营业务','商业预约等后续业务另行定义。']]:[['体育内容','本地体育资讯及内容运营。'],['同城服务','运动相关服务与供需信息。'],['协作与治理','发布、匹配及办理规则另行定义。']]).map(([t,d],i)=>`<div class="card future-step"><span>0${i+1}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><div class="notice neutral mt">${I('info')}<span>这是规划预览，没有新增业务权限、订单或管理菜单。赛事运营、场馆运营与内容服务的正式权限按各业务授权，不相互自动继承。</span></div><div class="actions"><button class="btn primary" data-action="workspace">返回赛事运营</button></div>`}
document.addEventListener('click',e=>{const el=e.target.closest('[data-platform]');if(!el)return;const a=el.dataset.platform;if(a==='city'){UI.modal('保定 · 当前城市',`<p>AI运动以保定的本地运动服务为起点。</p><p class="muted mt">当前界面保留城市站位置；本轮不提供其他城市服务或切换。</p>`);return}if(a==='sport'){sport=el.dataset.id;events(window.renderConsumerShell)}if(a==='status'){status=el.dataset.id;events(window.renderConsumerShell)}if(a==='search'){search=document.getElementById('event-query').value.trim();events(window.renderConsumerShell)}if(a==='reset-filters'){sport='all';status='all';search='';events(window.renderConsumerShell)}});
return{home,events,upcoming,bUpcoming,cityMark,scene};
})();

